 1: /**
 2:  * Iterates over all contiguous matches of the regular expression over the
 3:  * text. Stops as soon as the regular expression no longer matches at the
 4:  * current position.
 5:  */
 6: export function* execAll(re: RegExp, text: string) {
 7:   re = new RegExp(re, re.flags + (re.sticky ? '' : 'y'));
 8: 
 9:   while (true) {
10:     const match = re.exec(text);
11: 
12:     // We break out of the loop if there is no match or if the empty string is
13:     // matched because no progress will be made and it will loop indefinitely.
14:     if (!match?.[0]) break;
15: 
16:     yield match;
17:   }
18: }
